#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<int> dp(n + 1, 0);
    vector<int> a(n + 1);
    for (int i = 1; i <= n; i++) cin >> a[i];

    for (int i = n; i >= 1; i--) {
        dp[i] = a[i];
        for (int j = i + 1; j <= n; j++) {
            if (a[j] % a[i] == 0) {
                dp[i] = max(dp[i], dp[j] + a[i]);
            }
        }
    }

    int max_val = 0;
    for (int i = 1; i <= n; i++) {
        max_val = max(max_val, dp[i]);
    }
    cout << max_val << endl;
    return 0;
}
